import math
import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64
.extern .shared .align 4 .b8 smem[];
.visible .entry convt3d_kernel(
    .param .u64 in_ptr,
    .param .u64 w_ptr,
    .param .u64 b_ptr,
    .param .u64 out_ptr,
    .param .u32 N,
    .param .u32 Cin,
    .param .u32 Cout,
    .param .u32 Din,
    .param .u32 Hin,
    .param .u32 Win,
    .param .u32 Kd,
    .param .u32 Kh,
    .param .u32 Kw,
    .param .u32 sD,
    .param .u32 sH,
    .param .u32 sW,
    .param .s32 pD,
    .param .s32 pH,
    .param .s32 pW,
    .param .u32 groups,
    .param .u32 Dout,
    .param .u32 Hout,
    .param .u32 Wout,
    .param .u32 has_bias
)
{
    .reg .pred  %p<32>;
    .reg .b32   %r<160>;
    .reg .b64   %rd<160>;
    .reg .f32   %f<10>;
    // moved to module scope: .extern .shared .align 4 .b8 smem[];
    // Load parameters
    ld.param.u64    %rd10, [in_ptr];
    ld.param.u64    %rd11, [w_ptr];
    ld.param.u64    %rd12, [b_ptr];
    ld.param.u64    %rd13, [out_ptr];
    ld.param.u32    %r10, [N];
    ld.param.u32    %r11, [Cin];
    ld.param.u32    %r12, [Cout];
    ld.param.u32    %r13, [Din];
    ld.param.u32    %r14, [Hin];
    ld.param.u32    %r15, [Win];
    ld.param.u32    %r16, [Kd];
    ld.param.u32    %r17, [Kh];
    ld.param.u32    %r18, [Kw];
    ld.param.u32    %r19, [sD];
    ld.param.u32    %r20, [sH];
    ld.param.u32    %r21, [sW];
    ld.param.s32    %r22, [pD];
    ld.param.s32    %r23, [pH];
    ld.param.s32    %r24, [pW];
    ld.param.u32    %r25, [groups];
    ld.param.u32    %r26, [Dout];
    ld.param.u32    %r27, [Hout];
    ld.param.u32    %r28, [Wout];
    ld.param.u32    %r29, [has_bias];
    // Compute linear thread id
    mov.u32         %r30, %tid.x;
    mov.u32         %r31, %ctaid.x;
    mov.u32         %r32, %ntid.x;
    mad.lo.s32      %r33, %r31, %r32, %r30; // idx
    // total = N*Cout*Dout*Hout*Wout
    mul.lo.u32      %r34, %r10, %r12;
    mul.lo.u32      %r35, %r34, %r26;
    mul.lo.u32      %r36, %r35, %r27;
    mul.lo.u32      %r37, %r36, %r28; // total
    setp.ge.u32     %p0, %r33, %r37;
    @%p0 bra        DONE;
    // Compute per-CTA constant: whether all threads in this CTA share the same co
    // blockStart = ctaid.x * ntid.x
    mul.lo.u32      %r100, %r31, %r32;           // blockStart
    // blockEnd = min(blockStart + ntid.x - 1, total - 1)
    add.u32         %r101, %r100, %r32;
    add.u32         %r101, %r101, 0xffffffff;    // blockStart + ntid.x - 1
    add.u32         %r102, %r37, 0xffffffff;     // total - 1
    setp.gt.u32     %p1, %r101, %r102;
    @!%p1 bra       NO_CLAMP_BE;
    mov.u32         %r101, %r102;
NO_CLAMP_BE:
    // ohwd = Dout*Hout*Wout
    mul.lo.u32      %r103, %r26, %r27;
    mul.lo.u32      %r104, %r103, %r28;          // ohwd
    // qStart = blockStart / ohwd; qEnd = blockEnd / ohwd
    div.u32         %r105, %r100, %r104;
    div.u32         %r106, %r101, %r104;
    // co_start = qStart % Cout; co_end = qEnd % Cout
    rem.u32         %r107, %r105, %r12;          // co_start
    rem.u32         %r108, %r106, %r12;          // co_end
    setp.eq.u32     %p2, %r107, %r108;           // same_co?
    // Decompose index into (n, co, d, h, w)
    mov.u32         %r38, %r33;        // t = idx
    rem.u32         %r39, %r38, %r28;  // w_out
    div.u32         %r38, %r38, %r28;
    rem.u32         %r40, %r38, %r27;  // h_out
    div.u32         %r38, %r38, %r27;
    rem.u32         %r41, %r38, %r26;  // d_out
    div.u32         %r38, %r38, %r26;
    rem.u32         %r42, %r38, %r12;  // co
    div.u32         %r43, %r38, %r12;  // n
    // Compute group parameters
    // Cout_per_group = Cout / groups
    // Cin_per_group  = Cin / groups
    div.u32         %r44, %r12, %r25;  // Cout_g
    div.u32         %r45, %r11, %r25;  // Cin_g
    // group_id = co / Cout_g
    div.u32         %r46, %r42, %r44;  // group_id
    rem.u32         %r47, %r42, %r44;  // co_g within group
    mul.lo.u32      %r48, %r46, %r45;  // ci_start
    add.u32         %r49, %r48, %r45;  // ci_end
    // Prepare 64-bit constants
    cvt.u64.u32     %rd20, %r11;       // Cin
    cvt.u64.u32     %rd21, %r13;       // Din
    cvt.u64.u32     %rd22, %r14;       // Hin
    cvt.u64.u32     %rd23, %r15;       // Win
    cvt.u64.u32     %rd24, %r12;       // Cout
    cvt.u64.u32     %rd25, %r26;       // Dout
    cvt.u64.u32     %rd26, %r27;       // Hout
    cvt.u64.u32     %rd27, %r28;       // Wout
    cvt.u64.u32     %rd28, %r44;       // Cout_g
    cvt.u64.u32     %rd29, %r16;       // Kd
    cvt.u64.u32     %rd30, %r17;       // Kh
    cvt.u64.u32     %rd31, %r18;       // Kw
    // Convert selected indices to 64-bit where needed
    cvt.u64.u32     %rd40, %r43;       // n
    cvt.u64.u32     %rd41, %r42;       // co
    cvt.u64.u32     %rd42, %r41;       // d_out
    cvt.u64.u32     %rd43, %r40;       // h_out
    cvt.u64.u32     %rd44, %r39;       // w_out
    cvt.u64.u32     %rd45, %r47;       // co_g
    // Precompute kernel products
    mul.lo.u32      %r109, %r17, %r18;        // Kh*Kw
    mul.lo.u32      %r110, %r16, %r109;       // Kd*Kh*Kw
    // If all threads in CTA share co, stage that filter slice in shared memory
    @!%p2 bra       NO_STAGE_WEIGHTS;
    // Compute staging parameters based on co_start (r107)
    div.u32         %r111, %r107, %r44;       // stage_group_id = co_start / Cout_g
    rem.u32         %r112, %r107, %r44;       // stage_co_g = co_start % Cout_g
    mul.lo.u32      %r113, %r111, %r45;       // stage_ci_start = stage_group_id * Cin_g
    // L = Cin_g * (Kd*Kh*Kw)
    mul.lo.u32      %r114, %r45, %r110;      // L
    // smem base
     mov.u64         %rd90, smem;
    // Cooperative load loop over L elements
    mov.u32         %r115, %r30;             // l = tid
WL_LOOP:
    setp.ge.u32     %p3, %r115, %r114;
    @%p3 bra        WL_DONE;
    // Map l -> (ci_off, kd, kh, kw)
    div.u32         %r116, %r115, %r110;     // ci_off
    rem.u32         %r117, %r115, %r110;     // rem1
    div.u32         %r118, %r117, %r109;     // kd
    rem.u32         %r119, %r117, %r109;     // rem2
    div.u32         %r120, %r119, %r18;      // kh
    rem.u32         %r121, %r119, %r18;      // kw
    // ci_global = stage_ci_start + ci_off
    add.u32         %r122, %r113, %r116;     // ci_global
    // Global weight index for (ci_global, stage_co_g, kd, kh, kw)
    cvt.u64.u32     %rd91, %r122;            // ci
    mov.u64         %rd92, %rd91;
    mul.lo.u64      %rd92, %rd92, %rd28;     // * Cout_g
    cvt.u64.u32     %rd93, %r112;            // stage_co_g
    add.u64         %rd92, %rd92, %rd93;     // + co_g
    mul.lo.u64      %rd92, %rd92, %rd29;     // * Kd
    cvt.u64.u32     %rd94, %r118;            // kd
    add.u64         %rd92, %rd92, %rd94;     // + kd
    mul.lo.u64      %rd92, %rd92, %rd30;     // * Kh
    cvt.u64.u32     %rd95, %r120;            // kh
    add.u64         %rd92, %rd92, %rd95;     // + kh
    mul.lo.u64      %rd92, %rd92, %rd31;     // * Kw
    cvt.u64.u32     %rd96, %r121;            // kw
    add.u64         %rd92, %rd92, %rd96;     // + kw
    shl.b64         %rd97, %rd92, 2;         // * 4 bytes
    add.u64         %rd98, %rd11, %rd97;     // w addr
    ld.global.f32   %f1, [%rd98];
    // Store to shared at offset l
    cvt.u64.u32     %rd99, %r115;
    shl.b64         %rd100, %rd99, 2;
    add.u64         %rd101, %rd90, %rd100;
    st.shared.f32   [%rd101], %f1;
    add.u32         %r115, %r115, %r32;      // l += ntid.x
    bra             WL_LOOP;
WL_DONE:
    bar.sync 0;
NO_STAGE_WEIGHTS:
    // Initialize accumulator with bias or zero
    mov.f32         %f0, 0f00000000;   // 0.0
    setp.ne.u32     %p4, %r29, 0;
    @!%p4 bra       NO_BIAS_INIT;
    // load bias[co]
    shl.b64         %rd50, %rd41, 2;   // co * 4
    add.u64         %rd51, %rd12, %rd50;
    ld.global.f32   %f0, [%rd51];
NO_BIAS_INIT:
    // kd loop init
    mov.u32         %r50, 0;           // kd = 0
KD_LOOP:
    setp.ge.u32     %p5, %r50, %r16;
    @%p5 bra        KD_DONE;
    // Compute di validity for this kd
    // tmpd = (int)d_out + pD - (int)kd
    cvt.s32.u32     %r60, %r41;        // d_out s32
    add.s32         %r60, %r60, %r22;  // d_out + pD
    cvt.s32.u32     %r61, %r50;        // kd s32
    sub.s32         %r60, %r60, %r61;  // tmpd
    // Check divisibility and range for di
    cvt.s32.u32     %r62, %r19;        // sD s32
    rem.s32         %r63, %r60, %r62;  // remd
    setp.eq.s32     %p6, %r63, 0;
    div.s32         %r64, %r60, %r62;  // di
    setp.ge.s32     %p7, %r64, 0;
    cvt.s32.u32     %r65, %r13;        // Din s32
    setp.lt.s32     %p8, %r64, %r65;
    and.pred        %p9, %p6, %p7;
    and.pred        %p9, %p9, %p8;
    @!%p9 bra       KD_CONT;
    cvt.u32.s32     %r66, %r64;        // di_u32
    // kh loop init
    mov.u32         %r51, 0;           // kh = 0
KH_LOOP:
    setp.ge.u32     %p10, %r51, %r17;
    @%p10 bra       KH_DONE;
    // Compute hi validity for this kh
    cvt.s32.u32     %r70, %r40;        // h_out s32
    add.s32         %r70, %r70, %r23;  // + pH
    cvt.s32.u32     %r71, %r51;        // kh s32
    sub.s32         %r70, %r70, %r71;  // tmph
    cvt.s32.u32     %r72, %r20;        // sH s32
    rem.s32         %r73, %r70, %r72;  // remh
    setp.eq.s32     %p11, %r73, 0;
    div.s32         %r74, %r70, %r72;  // hi
    setp.ge.s32     %p12, %r74, 0;
    cvt.s32.u32     %r75, %r14;        // Hin s32
    setp.lt.s32     %p13, %r74, %r75;
    and.pred        %p14, %p11, %p12;
    and.pred        %p14, %p14, %p13;
    @!%p14 bra      KH_CONT;
    cvt.u32.s32     %r76, %r74;        // hi_u32
    // kw loop init
    mov.u32         %r52, 0;           // kw = 0
KW_LOOP:
    setp.ge.u32     %p15, %r52, %r18;
    @%p15 bra       KW_DONE;
    // Compute wi validity for this kw
    cvt.s32.u32     %r80, %r39;        // w_out s32
    add.s32         %r80, %r80, %r24;  // + pW
    cvt.s32.u32     %r81, %r52;        // kw s32
    sub.s32         %r80, %r80, %r81;  // tmpw
    cvt.s32.u32     %r82, %r21;        // sW s32
    rem.s32         %r83, %r80, %r82;  // remw
    setp.eq.s32     %p16, %r83, 0;
    div.s32         %r84, %r80, %r82;  // wi
    setp.ge.s32     %p17, %r84, 0;
    cvt.s32.u32     %r85, %r15;        // Win s32
    setp.lt.s32     %p18, %r84, %r85;
    and.pred        %p16, %p16, %p17;
    and.pred        %p16, %p16, %p18;
    @!%p16 bra      KW_CONT;
    cvt.u32.s32     %r86, %r84;        // wi_u32
    // ci loop
    mov.u32         %r53, %r48;        // ci = ci_start
CI_LOOP:
    setp.ge.u32     %p0, %r53, %r49;
    @%p0 bra        CI_DONE;
    // Input index: ((((n)*Cin + ci)*Din + di)*Hin + hi)*Win + wi
    cvt.u64.u32     %rd60, %r53;               // ci
    mov.u64         %rd61, %rd40;              // t = n
    mul.lo.u64      %rd61, %rd61, %rd20;       // * Cin
    add.u64         %rd61, %rd61, %rd60;       // + ci
    mul.lo.u64      %rd61, %rd61, %rd21;       // * Din
    cvt.u64.u32     %rd62, %r66;               // di
    add.u64         %rd61, %rd61, %rd62;       // + di
    mul.lo.u64      %rd61, %rd61, %rd22;       // * Hin
    cvt.u64.u32     %rd63, %r76;               // hi
    add.u64         %rd61, %rd61, %rd63;       // + hi
    mul.lo.u64      %rd61, %rd61, %rd23;       // * Win
    cvt.u64.u32     %rd64, %r86;               // wi
    add.u64         %rd61, %rd61, %rd64;       // + wi
    shl.b64         %rd65, %rd61, 2;           // * 4 bytes
    add.u64         %rd66, %rd10, %rd65;       // in addr
    ld.global.f32   %f1, [%rd66];
    // Weight load: either from staged shared memory (if same co across CTA) or from global
    @%p2 bra        USE_SMEM_WEIGHT;
    // --- Global weight load path ---
    // Weight index: ((((ci)*Cout_g + co_g)*Kd + kd)*Kh + kh)*Kw + kw
    cvt.u64.u32     %rd70, %r53;              // ci
    mul.lo.u64      %rd70, %rd70, %rd28;      // * Cout_g
    add.u64         %rd70, %rd70, %rd45;      // + co_g
    mul.lo.u64      %rd70, %rd70, %rd29;      // * Kd
    cvt.u64.u32     %rd71, %r50;              // kd
    add.u64         %rd70, %rd70, %rd71;      // + kd
    mul.lo.u64      %rd70, %rd70, %rd30;      // * Kh
    cvt.u64.u32     %rd72, %r51;              // kh
    add.u64         %rd70, %rd70, %rd72;      // + kh
    mul.lo.u64      %rd70, %rd70, %rd31;      // * Kw
    cvt.u64.u32     %rd73, %r52;              // kw
    add.u64         %rd70, %rd70, %rd73;      // + kw
    shl.b64         %rd74, %rd70, 2;          // * 4 bytes
    add.u64         %rd75, %rd11, %rd74;      // w addr
    ld.global.f32   %f2, [%rd75];
    bra             HAVE_WEIGHT;
USE_SMEM_WEIGHT:
    // --- Shared memory weight load path ---
    // ci_off = ci - ci_start
    sub.u32         %r123, %r53, %r48;        // ci_off
    // l = ci_off*(Kd*Kh*Kw) + kd*(Kh*Kw) + kh*Kw + kw
    mul.lo.u32      %r124, %r123, %r110;      // ci_off * Kd*Kh*Kw
    mul.lo.u32      %r125, %r50, %r109;       // kd * Kh*Kw
    add.u32         %r124, %r124, %r125;
    mul.lo.u32      %r126, %r51, %r18;        // kh * Kw
    add.u32         %r124, %r124, %r126;
    add.u32         %r124, %r124, %r52;       // + kw
    cvt.u64.u32     %rd102, %r124;
    shl.b64         %rd103, %rd102, 2;
     mov.u64         %rd104, smem;
    add.u64         %rd105, %rd104, %rd103;
    ld.shared.f32   %f2, [%rd105];
HAVE_WEIGHT:
    // acc += x * w
    fma.rn.f32      %f0, %f1, %f2, %f0;
    add.u32         %r53, %r53, 1;
    bra             CI_LOOP;
CI_DONE:
KW_CONT:
    add.u32         %r52, %r52, 1;
    bra             KW_LOOP;
KW_DONE:
KH_CONT:
    add.u32         %r51, %r51, 1;
    bra             KH_LOOP;
KH_DONE:
KD_CONT:
    add.u32         %r50, %r50, 1;
    bra             KD_LOOP;
KD_DONE:
    // Store output at index ((((n)*Cout + co)*Dout + d)*Hout + h)*Wout + w
    mov.u64         %rd80, %rd40;              // n
    mul.lo.u64      %rd80, %rd80, %rd24;       // * Cout
    add.u64         %rd80, %rd80, %rd41;       // + co
    mul.lo.u64      %rd80, %rd80, %rd25;       // * Dout
    add.u64         %rd80, %rd80, %rd42;       // + d_out
    mul.lo.u64      %rd80, %rd80, %rd26;       // * Hout
    add.u64         %rd80, %rd80, %rd43;       // + h_out
    mul.lo.u64      %rd80, %rd80, %rd27;       // * Wout
    add.u64         %rd80, %rd80, %rd44;       // + w_out
    shl.b64         %rd81, %rd80, 2;           // * 4
    add.u64         %rd82, %rd13, %rd81;       // out addr
    st.global.f32   [%rd82], %f0;
DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("convt3d_kernel")

class _ParamContainer(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, groups, bias):
        super().__init__()
        kd, kh, kw = kernel_size
        assert out_channels % groups == 0
        self.weight = nn.Parameter(torch.empty(in_channels, out_channels // groups, kd, kh, kw))
        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
        else:
            self.register_parameter("bias", None)
        # Reset parameters similar to PyTorch ConvTranspose3d
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in, _ = nn.init._calculate_fan_in_and_fan_out(self.weight)
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            nn.init.uniform_(self.bias, -bound, bound)

class ModelNew(nn.Module):
    """
    Performs a transposed 3D convolution operation with asymmetric input and kernel sizes.

    Args:
        in_channels (int): Number of channels in the input tensor.
        out_channels (int): Number of channels produced by the convolution.
        kernel_size (tuple): Tuple of 3 integers representing the kernel size in the form (depth, height, width).
        stride (tuple, optional): Tuple of 3 integers representing the stride in the form (depth, height, width). Defaults to (1, 1, 1).
        padding (tuple, optional): Tuple of 3 integers representing the padding in the form (depth, height, width). Defaults to (0, 0, 0).
        output_padding (tuple, optional): Tuple of 3 integers representing the output padding in the form (depth, height, width). Defaults to (0, 0, 0).
        groups (int, optional): Number of blocked connections from input channels to output channels. Defaults to 1.
        bias (bool, optional): If `True`, adds a learnable bias to the output. Defaults to `False`.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple, stride: tuple = (1, 1, 1), padding: tuple = (0, 0, 0), output_padding: tuple = (0, 0, 0), groups: int = 1, bias: bool = False):
        super().__init__()
        assert isinstance(kernel_size, (tuple, list)) and len(kernel_size) == 3
        assert isinstance(stride, (tuple, list)) and len(stride) == 3
        assert isinstance(padding, (tuple, list)) and len(padding) == 3
        assert isinstance(output_padding, (tuple, list)) and len(output_padding) == 3
        self.in_channels = int(in_channels)
        self.out_channels = int(out_channels)
        self.kernel_size = tuple(int(x) for x in kernel_size)
        self.stride = tuple(int(x) for x in stride)
        self.padding = tuple(int(x) for x in padding)
        self.output_padding = tuple(int(x) for x in output_padding)
        self.groups = int(groups)
        self.bias_flag = bool(bias)
        self.conv_transpose3d = _ParamContainer(self.in_channels, self.out_channels, self.kernel_size, self.groups, self.bias_flag)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if not x.is_cuda:
            raise RuntimeError("ModelNew requires CUDA tensor input.")
        if x.dtype != torch.float32:
            raise RuntimeError("ModelNew supports float32 tensors only.")
        if x.dim() != 5:
            raise RuntimeError("Input must be NCDHW (5D).")
        N, Cin, Din, Hin, Win = x.shape
        if Cin != self.in_channels:
            raise RuntimeError("Input channels mismatch.")
        Kd, Kh, Kw = self.kernel_size
        sD, sH, sW = self.stride
        pD, pH, pW = self.padding
        oD, oH, oW = self.output_padding
        groups = self.groups
        if Cin % groups != 0 or self.out_channels % groups != 0:
            raise RuntimeError("Invalid groups configuration.")
