    // blockStart = ctaid.x * ntid.x
    mul.lo.u32      %r100, %r31, %r32;           // blockStart
    // blockEnd = min(blockStart + ntid.x - 1, total - 1)
    add.u32         %r101, %r100, %r32;
    add.u32         %r101, %r101, 0xffffffff;    // blockStart + ntid.x - 1
    add.u32         %r102, %r37, 0xffffffff;     // total - 1
    setp.gt.u32     %p1, %r101, %r102;
    @!%p1 bra       NO_CLAMP_BE;
    mov.u32         %r101, %r102;
NO_CLAMP_BE:
