    mul.lo.u32      %r109, %r17, %r18;        // Kh*Kw
    mul.lo.u32      %r110, %r16, %r109;       // Kd*Kh*Kw
    // If all threads in CTA share co, stage that filter slice in shared memory
    @!%p2 bra       NO_STAGE_WEIGHTS;
    // Compute staging parameters based on co_start (r107)
    div.u32         %r111, %r107, %r44;       // stage_group_id = co_start / Cout_g
    rem.u32         %r112, %r107, %r44;       // stage_co_g = co_start % Cout_g
    mul.lo.u32      %r113, %r111, %r45;       // stage_ci_start = stage_group_id * Cin_g
    // L = Cin_g * (Kd*Kh*Kw)
    mul.lo.u32      %r114, %r45, %r110;      // L
    // smem base
    mov.u64         %rd90, smem;
    // Cooperative load loop over L elements
    mov.u32         %r115, %r30;             // l = tid
WL_LOOP:
    setp.ge.u32     %p3, %r115, %r114;
    @%p3 bra        WL_DONE;
