_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("convt3d_kernel")

class _ParamContainer(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, groups, bias):
        super().__init__()
        kd, kh, kw = kernel_size
        assert out_channels % groups == 0
        self.weight = nn.Parameter(torch.empty(in_channels, out_channels // groups, kd, kh, kw))
        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
        else:
            self.register_parameter("bias", None)
        # Reset parameters similar to PyTorch ConvTranspose3d
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in, _ = nn.init._calculate_fan_in_and_fan_out(self.weight)
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            nn.init.uniform_(self.bias, -bound, bound)

